const chargedSourceNodes=new Set(['MemberExpression','CallExpression','NewExpression','IfStatement','LogicalExpression','UnaryExpression','BinaryExpression','AssignmentExpression','UpdateExpression','ReturnStatement','ThrowStatement','VariableDeclarator','BreakStatement','ForStatement','WhileStatement','ConditionalExpression','TryStatement','CatchClause','TemplateLiteral']);
function continuityUnits(node,skip){let total=0;function visit(n){if(!n||typeof n!=='object'||n===skip)return;if(chargedSourceNodes.has(n.type))total++;if(n.type==='ArrayExpression')total+=1+n.elements.length;if(n.type==='ObjectExpression')total+=1+n.properties.length;for(const [key,value]of Object.entries(n))if(key!=='loc')if(Array.isArray(value))value.forEach(visit);else if(value&&typeof value==='object')visit(value);}visit(node);return total;}
