 const node=48+2*11+2,initialization=46+32+1,captureWork=32*(25+3*11)+71+9*11+30+49+11+64;assert.equal(node,72);assert.equal(captureWork,2180);assert.ok(initialization<=128&&captureWork<=2560);
 // Per-node structural census counts all alternate/stop branches. Only two data helper bodies recur per node (child/sibling); the unique reciprocal alternate helper is fixed. Source calls to native primitives are logical units, not internal native CPU claims.
 const canonical=100*128+1536+800,cache=129*46+128,contexts=32*55+128,visibility=128*48+128,liveAndClosure=768;assert.equal(canonical,15136);assert.ok(canonical<=15360);assert.ok(cache<=6144);assert.ok(contexts+visibility+liveAndClosure<=9216);const fixed=4096+15360+6144+9216+2048;assert.equal(fixed,36864);assert.equal(3072*node+fixed,258048);assert.equal(258578+2560+64,261202);assert.ok(Math.max(258048+64,261202+64)<=262144);
