function originalParityReact(){return Function('var workInProgressRootSkippedLanes=0;const hostTransitionProviderCursor={current:null};function formatProdErrorMessage(n){return "React "+n;}function objectIs(a,b){return Object.is(a,b);}function propagateContextChanges(){throw Error("unexpected context propagation");}\n'+['FiberNode','createFiberImplClass','createWorkInProgress','bubbleProperties','propagateParentContextChanges','bailoutOnAlreadyFinishedWork'].map(reactDeclaration).join('\n')+'\nreturn {FiberNode,createWorkInProgress,bubbleProperties,bailoutOnAlreadyFinishedWork};')();}
async function rootParityResult(held=false,change){const currentSource=readAdapterSource(),src=held?eraseRootRelation(currentSource):currentSource,tx=await import('./instrument.mjs'),wrapped=tx.transform('react',new URL('./adapter.mjs',import.meta.url).pathname).code,ast=continuityAst(wrapped),body=['recursivelyTraverseLayoutEffects','commitLayoutEffectOnFiber'].map(name=>{const n=ast.body.find(n=>n.id?.name===name);assert.ok(n);return wrapped.slice(n.start,n.end);}).join('\n'),makeLayout=Function('__lh','commitHookEffectListMount',body+';return commitLayoutEffectOnFiber;'),m=await import('data:text/javascript;base64,'+Buffer.from(src+BOUNDARY_FIXTURE+CONTINUITY_FIXTURE+ROOT_PARITY_FIXTURE+'\n//rootParity'+(++continuitySerial)).toString('base64'));return m.rootParityFacts(originalParityReact(),makeLayout,change);}
